/* Vínculo real gerado da planilha Relação Servidores - Api Nova (2).xlsx. */

/* A coluna B foi usada como matrícula e a coluna G como código da lotação. */

/* O banco possui uma única lotacao_id por servidor. Matrículas com mais de uma lotação ficam fora da atualização e são listadas no relatório final. */

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_lotacao_execucao;

CREATE TEMPORARY TABLE tmp_lotacao_execucao (matricula VARCHAR(255) NOT NULL, numero_lotacao VARCHAR(100) NOT NULL, PRIMARY KEY (matricula), KEY idx_import_lotacao (numero_lotacao)) ENGINE=InnoDB;

