SELECT i.matricula, i.numero_lotacao, 'MATRICULA_NAO_ENCONTRADA' AS problema FROM tmp_lotacao_execucao i LEFT JOIN servidores s ON TRIM(s.matricula)=TRIM(i.matricula) AND s.deleted_at IS NULL WHERE s.id IS NULL;

SELECT i.matricula, i.numero_lotacao, 'LOTACAO_NAO_ENCONTRADA' AS problema FROM tmp_lotacao_execucao i LEFT JOIN lotacoes l ON TRIM(l.codigo)=TRIM(i.numero_lotacao) WHERE l.id IS NULL;

SELECT s.id, s.matricula, s.nome, i.numero_lotacao, 'PREVIA_VINCULO' AS tipo FROM tmp_lotacao_execucao i INNER JOIN servidores s ON TRIM(s.matricula)=TRIM(i.matricula) AND s.deleted_at IS NULL INNER JOIN lotacoes l ON TRIM(l.codigo)=TRIM(i.numero_lotacao);

UPDATE servidores s INNER JOIN tmp_lotacao_execucao i ON TRIM(i.matricula)=TRIM(s.matricula) INNER JOIN lotacoes l ON TRIM(l.codigo)=TRIM(i.numero_lotacao) SET s.lotacao_id=l.id, s.updated_at=CURRENT_TIMESTAMP WHERE s.deleted_at IS NULL;

SELECT ROW_COUNT() AS servidores_atualizados;

/* Matrículas com múltiplos códigos na planilha: não foram atualizadas automaticamente. */

/* Confirme somente após revisar os SELECTs acima. */

COMMIT;
